import React, { useEffect, useRef, useState } from 'react';
import { portfolioData, skillIcons, techColors } from '../../data/portfolioData';
import './Skills.css';

const Skills = () => {
  const sectionRef = useRef(null);
  const [activeCategory, setActiveCategory] = useState(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -100px 0px' }
    );

    if (sectionRef.current) {
      const revealElements = sectionRef.current.querySelectorAll('.reveal');
      revealElements.forEach((el) => observer.observe(el));
    }
    return () => observer.disconnect();
  }, []);

  const categories = Object.entries(portfolioData.skills);
  const totalSkills = Object.values(portfolioData.skills).flat().length;

  return (
    <section id="skills" className="skills" ref={sectionRef} aria-labelledby="skills-title">
      <div className="container">
        <div className="section-header reveal">
          <span className="section-tag">Technical Skills</span>
          <h2 id="skills-title" className="section-title">What I Do</h2>
          <p className="section-subtitle">A comprehensive toolkit built through hands-on experience across data analytics, cloud platforms, and visualization.</p>
        </div>

        {/* Skills Overview */}
        <div className="skills-overview reveal stagger-children">
          <div className="overview-stat">
            <span className="stat-number" data-count={totalSkills}>0</span>
            <span className="stat-label">Technologies Mastered</span>
          </div>
          <div className="overview-stat">
            <span className="stat-number" data-count={categories.length}>0</span>
            <span className="stat-label">Skill Categories</span>
          </div>
          <div className="overview-stat">
            <span className="stat-number">2+</span>
            <span className="stat-label">Years Experience</span>
          </div>
        </div>

        {/* Categories */}
        <div className="skills-categories reveal stagger-children">
          {categories.map(([category, skills], index) => (
            <article
              key={category}
              className={`skill-category ${activeCategory === category ? 'active' : ''}`}
              onClick={() => setActiveCategory(activeCategory === category ? null : category)}
              style={{ '--delay': `${index * 100}ms` }}
            >
              <div className="category-header">
                <div className="category-icon" aria-hidden="true">
                  {skillIcons[category] || '⚡'}
                </div>
                <div className="category-info">
                  <h3 className="category-name">{category}</h3>
                  <p className="category-count">{skills.length} skills</p>
                </div>
                <div className="category-expand" aria-hidden="true">
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <polyline points="6 9 12 15 18 9" />
                  </svg>
                </div>
              </div>

              <div className="category-skills">
                <div className="skills-grid">
                  {skills.map((skill, skillIndex) => (
                    <button
                      key={skill}
                      className="skill-tag"
                      style={{
                        '--skill-color': techColors[skill] || 'var(--color-primary)',
                        '--delay': `${skillIndex * 50}ms`
                      }}
                      onClick={(e) => e.stopPropagation()}
                      aria-label={`${skill} - Click for details`}
                    >
                      <span className="skill-name">{skill}</span>
                      <span className="skill-bar" aria-hidden="true">
                        <span className="skill-progress" />
                      </span>
                    </button>
                  ))}
                </div>

                {activeCategory === category && (
                  <div className="category-detail">
                    <div className="detail-content">
                      <h4>Proficiency Details</h4>
                      <p>These skills have been applied in real-world projects including AWS document processing pipelines, Power BI dashboards, and data quality validation workflows.</p>
                      <div className="detail-tags">
                        {skills.map((skill) => (
                          <span key={skill} className="detail-tag" style={{ '--tag-color': techColors[skill] || 'var(--color-primary)' }}>
                            {skill}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </article>
          ))}
        </div>

        {/* Proficiency Legend */}
        <div className="proficiency-legend reveal">
          <h4>Proficiency Levels</h4>
          <div className="legend-items">
            <div className="legend-item">
              <div className="legend-bar">
                <div className="legend-fill" style={{ width: '90%' }} />
              </div>
              <span>Expert</span>
            </div>
            <div className="legend-item">
              <div className="legend-bar">
                <div className="legend-fill" style={{ width: '70%' }} />
              </div>
              <span>Advanced</span>
            </div>
            <div className="legend-item">
              <div className="legend-bar">
                <div className="legend-fill" style={{ width: '50%' }} />
              </div>
              <span>Intermediate</span>
            </div>
            <div className="legend-item">
              <div className="legend-bar">
                <div className="legend-fill" style={{ width: '30%' }} />
              </div>
              <span>Learning</span>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
